  zV = `Stel geen specifieke categorie voor, maar laat je fans de categorie selecteren die ze het meest geschikt vinden voor je spel. Het evenement zal nog steeds een link bevatten naar de nominatiepagina.`,
  BV = `Geen categorie`,
  VV = `Misschien was het de meeslepende gameplay of het aangrijpende verhaal... de goed ontwikkelde karakters, het vlekkeloze ontwerp of de verslavende multiplayeractie. Wat de reden ook is, de winnaar van Spel van het jaar voor 2020 is onmiddellijk een klassieker.`,
  HV = `Het VR-spel van het jaar bootst de realiteit niet gewoon na. Het voert je naar een betere realiteit. Dit spel buit de mogelijkheden van VR als medium ten volle uit en verlegt de grenzen van de virtuele wereld.`,
  UV = `Dit spel is al even uit. Het team heeft zijn creatieve ei al een tijd geleden gelegd, maar deze ontwikkelaars − goede ouders dat het zijn − blijven erop broeden. Na al die jaren krijgt dit spel nog altijd nieuwe inhoud.`,
  WV = `Er zijn spellen die gewoon niet hetzelfde zijn wanneer je ze alleen speelt. Misschien heb je een vriend nodig die je dekking geeft. Misschien heb je een vriend nodig die je in de rug kunt steken. Er wacht hoe dan ook pret voor diegenen die hun vrienden optrommelen om dit spel te spelen.`,
  GV = `Grafische stijl betekent niet streven naar een echte grafische getrouwheid (hoewel dat een nobele doelstelling is), maar het beschrijft een unieke uitstraling en gevoel die een heel spel doordrenken.`,
  KV = `De ontwerpers van dit spel bevinden zich met hun nieuwe perspectieven en verrassende hersenbrekers op de frontlinie van creatief experiment. Dit spel verrukte, inspireerde en vermaakte ons met innovatie die we nog nooit eerder in een spel tegenkwamen.`,
  qV = `Volharding, dat is wat er wordt beloond in dit spel. En het is niet voor eitjes. Dit is het moeilijkste spel waar we ooit voor zijn gevallen.`,
  JV = `Dit pareltje bleef misschien onder de radar, maar verdient eer en roem voor zijn geweldige soundtrack. Stopt de Oooh weer in OST! `,
  YV = `Er zijn zo van die dagen waarop enkel een stevige verhaallijn echt de dorst lest, en dit spel heeft verhaal in overvloed. Het is verslavender dan een soap en zo gepolijst als het script voor een prestigieuze tv-serie. Je liet ons emoties voelen: applaus!`,
  XV = `Dit spel is de remedie tegen een drukke dag. Het loopt vlotjes, is ontspannend en laat je zorgen als sneeuw voor de zon verdwijnen. Dit spel is jouw zenmoment.`,
  ZV = `Wil je je nominatie veranderen?`,
  QV = `Je kunt maar één spel voor elke categorie nomineren en je hebt %1$s al genomineerd voor deze categorie. Wil je liever %2$s in de plaats nomineren?`,
