  iH = `Je account is mogelijk beperkt. Om te voorkomen dat er valsgespeeld wordt bij het nomineren, kunnen alleen accounts die 5 dollar (USD) hebben uitgegeven op Steam deelnemen aan de Steam Awards. %1$s voor meer informatie.`,
  aH = `Je account is mogelijk beperkt. Om te voorkomen dat er valsgespeeld wordt bij het stemmen, kunnen alleen accounts die 5 dollar (USD) hebben uitgegeven op Steam deelnemen aan de Steam Awards. %1$s voor meer informatie.`,
