  IH = `Beste spel voor onderweg`,
  LH = `Misschien was het de meeslepende gameplay of het aangrijpende verhaal ... de goed ontwikkelde karakters, het vlekkeloze ontwerp of de verslavende multiplayeractie. Wat de reden ook is, de winnaar van deze prijs voor het Spel van het jaar is onmiddellijk een klassieker.`,
  RH = `Het VR-spel van het jaar bootst de realiteit niet gewoon na. Het voert je naar een betere realiteit. Dit spel buit de mogelijkheden van VR als medium ten volle uit en verlegt de grenzen van de virtuele wereld.`,
  zH = `Dit spel is al even uit. Het team heeft zijn creatieve ei al een tijd geleden gelegd, maar deze ontwikkelaars − goede ouders dat het zijn − blijven erop broeden. Na al die jaren krijgt dit spel nog steeds nieuwe inhoud.`,
  BH = `Er zijn spellen die gewoon niet hetzelfde zijn wanneer je ze alleen speelt. Misschien heb je een vriend nodig die je dekking geeft. Misschien heb je een vriend nodig om in de rug te steken. Hoe dan ook, wanneer je dit spel met vrienden speelt is het altijd leuker.`,
  VH = `Grafische stijl betekent niet het streven naar een echte grafische getrouwheid (hoewel dat op zich een nobel doel is), maar het beschrijft een unieke uitstraling en gevoel die een heel spel doordrenken.`,
  HH = `De ontwerpers van dit spel bevinden zich met hun nieuwe perspectieven en verrassende hersenbrekers op de frontlinie van creatief experimenteren. Dit spel verrukte, inspireerde en vermaakte ons met innovatie die we nog nooit eerder in een spel tegenkwamen.`,
  UH = `Volharding, dat is wat er wordt beloond in dit spel. En het is niet voor eitjes. Dit is het moeilijkste spel waar we ooit voor zijn gevallen.`,
  WH = `Deze onbezongen held verdient erkenning voor de uitstekende muzikale prestaties. Het is de ultieme soundtrack! `,
  GH = `Er zijn zo van die dagen waarop enkel een stevige verhaallijn echt de dorst lest, en dit spel heeft verhaal in overvloed. Het is verslavender dan een soap en zo gepolijst als het script voor een prestigeuze tv-serie. Je liet ons emoties voelen: applaus!`,
  KH = `Dit spel is de remedie tegen een drukke dag. Het loopt vlotjes, is ontspannend en laat je zorgen als sneeuw voor de zon verdwijnen. Dit spel is jouw zenmoment.`,
  qH = `Dit spel was zo goed dat je het overal mee naartoe wilde nemen. En dat heb je gedaan! Gelukkig was alles wat dit spel thuis zo leuk maakt, nog leuker onderweg.`,
