  dpe = `Anonieme gegevens over framesnelheid`,
  fpe = `Mogen we geanonimiseerde gegevens over framesnelheid verzamelen terwijl je met je Steam-account bent ingelogd en spellen speelt? We gebruiken deze gegevens om beter inzicht te krijgen in de spelcompatibiliteit en om Steam te verbeteren.`,
  ppe = `Anonieme gegevens over framesnelheid`,
  mpe = `Als je hier toestemming voor geeft, worden de gegevens over framesnelheid tijdens het spelen verzameld en opgeslagen zonder connectie met je Steam-account. Ze worden alleen gekoppeld aan het type hardware waarop je speelt. We gebruiken deze gegevens om beter inzicht te krijgen in de spelcompatibiliteit en om de ervaring op apparaten met Steam te verbeteren.`,
