  sme = `Grote verschillen tussen waarden in de grafiek (bijv. tussen %1$s en %2$s FPS) kunnen worden veroorzaakt door VSync, dat de framelevering synchroniseert met de vernieuwingsfrequentie van het beeldscherm om grafische storingen (tearing) te voorkomen. Dit kan ervoor zorgen dat samples zich concentreren rond de %1$s en %2$s FPS, zelfs wanneer de gemiddelde framesnelheid van het spel hiertussenin valt. Dit is normaal voor VSync en hoewel dit van invloed kan zijn op de frame pacing, zou het niet voor waarneembare haperingen moeten zorgen.`,
